    # Function to determine if cell is free
    def is_free(nx, ny):
        if not in_bounds(nx, ny):
            return False
        cell = grid[ny][nx]
        # Assume cell is free if it does not contain obstacle or opponent
        # Defensive: check for resource or goal
        if cell is None:
            return True
        if isinstance(cell, str):
            cell_lower = cell.lower()
            if 'obstacle' in cell_lower:
